  const newStyleEligible = Boolean(newStyle && request.workflowType === "concept" && request.sourceImage && scheme?.styleId === style.id && request.spaceType && Object.hasOwn(V8_SHARED.rooms, request.spaceType) && (request.renovationScope === "restyle" || request.renovationScope === "replace-soft-furnishings" || request.renovationScope === "empty-room") && request.providerPreference && (imageModelValues as readonly string[]).includes(request.providerPreference) && (request.lighting.lampState === "on" || request.lighting.lampState === "off") && !request.referenceImages?.length && !request.controlImages?.length && !request.mask && !request.editInstruction?.trim() && !request.customPrompt?.trim());
  const v10 = Boolean(scheme?.id.endsWith("-v10") && request.workflowType === "concept" && request.sourceImage && scheme.styleId === style.id && request.spaceType && Object.hasOwn(V8_SHARED.rooms, request.spaceType) && (request.renovationScope === "restyle" || request.renovationScope === "replace-soft-furnishings" || request.renovationScope === "empty-room") && request.providerPreference && (imageModelValues as readonly string[]).includes(request.providerPreference) && (request.lighting.lampState === "on" || request.lighting.lampState === "off") && !request.referenceImages?.length && !request.controlImages?.length && !request.mask && !request.editInstruction?.trim() && !request.customPrompt?.trim());
  if (scheme?.id.endsWith("-v10")) scheme = getDesignScheme(scheme.id.replace(/-v10$/u, "-v9"));
